        self.assertEqual(iso_week(2025, 12, 29), (2026, 1, 1))
        self.assertEqual(iso_week(2026, 1, 1), (2026, 1, 4))

    def test_dec29_31_can_be_next_year_week1(self):
        self.assertEqual(iso_week(2024, 12, 30), (2025, 1, 1))
        self.assertEqual(iso_week(2024, 12, 31), (2025, 1, 2))

    def test_jan1_3_can_be_previous_year_last_week(self):
        self.assertEqual(iso_week(2021, 1, 1), (2020, 53, 5))
        self.assertEqual(iso_week(2021, 1, 3), (2020, 53, 7))
        self.assertEqual(iso_week(2016, 1, 1), (2015, 53, 5))

