class Oracle(unittest.TestCase):
    def test_iso_week_matches_datetime_1583_to_9999(self):
        d = dt.date(1583, 1, 1)
        end = dt.date(9999, 12, 31)
        step = dt.timedelta(days=1)
        n = 0
        while d <= end:
            iy, iw, iwd = d.isocalendar()
            self.assertEqual(iso_week(d.year, d.month, d.day), (iy, iw, iwd), str(d))
            d += step
            n += 1
        self.assertGreater(n, 3_000_000)

    def test_from_iso_matches_datetime_all_weeks(self):
        for y in range(1583, 9999):
            weeks = 53 if dt.date(y, 12, 28).isocalendar()[1] == 53 else 52
            for w in range(1, weeks + 1):
                for wd in range(1, 8):
                    expect = dt.date.fromisocalendar(y, w, wd)
                    self.assertEqual(from_iso(y, w, wd), (expect.year, expect.month, expect.day),
                                     (y, w, wd))

    def test_from_iso_rejects_nonexistent_53_weeks_everywhere(self):
        for y in range(1583, 9999):
            if dt.date(y, 12, 28).isocalendar()[1] != 53:
                with self.assertRaises(ValueError):
                    from_iso(y, 53, 1)

    def test_roundtrip(self):
        d = dt.date(1600, 1, 1)
        while d < dt.date(2400, 1, 1):
            self.assertEqual(from_iso(*iso_week(d.year, d.month, d.day)), (d.year, d.month, d.day))
            d += dt.timedelta(days=1)

    def test_iso_week_rejects_every_invalid_day_in_century_range(self):
        for y in range(1900, 2101):
            for m in range(1, 13):
                for day in range(1, 32):
                    try:
                        dt.date(y, m, day)
                        valid = True
                    except ValueError:
                        valid = False
                    if valid:
                        iso_week(y, m, day)
                    else:
                        with self.assertRaises(ValueError):
                            iso_week(y, m, day)


